#include <iostream>
#include <vector>
#include <unordered_set>
using namespace std;
int main() {
    int n; if (cin >> n) {
        unordered_set<int> st;
        bool dup = false;
        for (int i = 0; i < n; i++) {
            int x; cin >> x;
            if (st.count(x)) dup = true;
            st.insert(x);
        }
        cout << (dup ? "true" : "false") << "\n";
    }
    return 0;
}

code.Java:
import java.util.Scanner;
import java.util.HashSet;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNextInt()) {
            int n = sc.nextInt();
            HashSet<Integer> st = new HashSet<>();
            boolean dup = false;
            for (int i = 0; i < n; i++) {
                int x = sc.nextInt();
                if (!st.add(x)) dup = true;
            }
            System.out.println(dup ? "true" : "false");
        }
    }
}

